  if(source.get("destWarehouseId")!=null)out.put(kind.equals("shipments")?"destWarehouseName":"warehouseName",organizations.reference(a,"warehouseId",id(source,"destWarehouseId"),entity).get("name"));
  else if(source.get("warehouseId")!=null)out.put("warehouseName",organizations.reference(a,"warehouseId",id(source,"warehouseId"),entity).get("name"));
  if(source.get("carrierId")!=null)out.put("carrierName",masterReferences.reference(a,"carrierId",id(source,"carrierId")).get("name"));
